@spec tm_rebuild_rule_spec  src=tests/specs/tm_rebuild_rule_spec.lua  loc=520  cases=20
@exercises midiManager (h.fm), trackerManager (h.tm), dataStore (h.ds), configManager (h.cm)
@surface   fm:dump, tm:markSwingStale, fm:notes, fm:modify, fm:assign, fm:ccs, tm:getChannel, tm:assignEvent, tm:flush, tm:rebuild, ds:assign, cm:set
@harness   mk{seed.notes, seed.ccs}

# Intent
  Phase 2 (two-frame timing): the rebuild rule. tm reconciles raw ppq
  with ppqL on every rebuild under three branches:
    - stale=true  & ppqL present  → raw rebuilt from ppqL (+ delay)
    - stale=false & raw matches   → no-op (steady state)
    - stale=false & raw disagrees → ppqL rederived from raw
  The rpb mark survives as authorship provenance but no longer gates the rule.

# Helpers
  @fn noteByPitch(dump, pitch)  @ 13-15
  @fn ccByCC(dump, ccNum)  @ 16-20

# Cases
  @case 'note with no ppqL gets ppqL written on first rebuild'  [harness]  @ 26-37
  @case 'note with ppqL disagreeing with raw gets ppqL rederived'  [harness]  @ 41-55
  @case 'cc with no ppqL gets ppqL written and uuid allocated'  [harness]  @ 59-69
  @case 'note with matching ppqL is left alone'  [harness]  @ 75-88
  @case 'matching ppqL under c58 is steady-state (predicted=raw within ε)'  [harness]  @ 92-109
  @case 'markSwingStale rebuilds raw from ppqL on next rebuild and clears the flag'  [harness]  @ 115-147
  @case 'markSwingStale restamps cc-event loc so column writes route correctly'  [harness]  @ 151-180
  @case 'markSwingStale(nil) marks all 16 channels'  [harness]  @ 184-209
  @case 'stale on event without ppqL falls through to disagreement (ppqL written, raw untouched)'  [harness]  @ 213-234
  @case 'rpb-stamped event with stale ppqL: predicted-check rederives from raw'  [harness]  @ 240-255
  @case 'global swing change reseats raw across all channels (ppqL preserved)'  [harness]  @ 265-287
  @case 'per-column swing change moves only the named channel'  [harness]  @ 291-309
  @case 'editing a referenced library entry reseats channels using it'  [harness]  @ 313-334
  @case 'reassigning a column slot to a different library entry reseats that channel'  [harness]  @ 338-362
  @case 'colSwing change marks only altered channels'  [harness]  @ 371-393
  @case 'swings library edit marks only channels using changed names'  [harness]  @ 397-420
  @case 'swings library edit of the global-swing name marks all 16'  [harness]  @ 424-444
  @case 'global swing change emits a single nil mark (covers all 16)'  [harness]  @ 448-464
  @case 'colSwing set to identical value emits no marks'  [harness]  @ 468-485
  @case 'non-swing config change does not flip stale (preserves externally-edited raw)'  [harness]  @ 489-518

